<template><div class="login-page"><el-card class="login-card"><h1>海卓智慧大脑</h1><p class="muted">登录你的数字员工工作台</p><el-form @submit.prevent="submit"><el-form-item label="手机号"><el-input v-model="mobile" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="password" type="password" show-password autocomplete="current-password"/></el-form-item><el-button type="primary" native-type="submit" :loading="auth.loading" class="full">登录</el-button></el-form><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mt"/></el-card></div></template>
<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../../stores/auth';const auth=useAuthStore();const router=useRouter();const mobile=ref('');const password=ref('');const error=ref('');async function submit(){error.value='';try{await auth.login(mobile.value,password.value);await router.push('/app/employees')}catch(e:any){error.value=e.response?.status===401?'手机号或密码错误':'登录失败，请稍后重试'}}</script>
